mapper.select:
SELECT id, openid, username, password, nickname, avatar_url, phone, gender, birthday, bio, coin_balance, status, last_login_time, create_time, update_time
FROM user
WHERE openid = #{openid}

SELECT id, openid, username, password, nickname, avatar_url, phone, gender, birthday, bio, coin_balance, status, last_login_time, create_time, update_time
FROM user
WHERE BINARY username = #{username}

SELECT id, openid, username, password, nickname, avatar_url, phone, gender, birthday, bio, coin_balance, status, last_login_time, create_time, update_time
FROM user
WHERE nickname = #{nickname}

SELECT id, openid, username, password, nickname, avatar_url, phone, gender, birthday, bio, coin_balance, status, last_login_time, create_time, update_time
FROM user
WHERE id = #{id}

mapper.update:
UPDATE user
nickname = #{nickname}, avatar_url = #{avatarUrl}, phone = #{phone}, gender = #{gender}, birthday = #{birthday}, bio = #{bio}, coin_balance = #{coinBalance}, username = #{username}, password = #{password}, status = #{status}, last_login_time = #{lastLoginTime},
WHERE id = #{id}
